    (ht : IsThreshold t), (∀ nodes : Finset (ShareNode F), nodes.card = t - 1 →
          ∀ obs : ShareNode F → F, TightAtObservation t nodes obs)

: ∀ {numAssets numStates : ℕ}
    (D : Fin numAssets → Fin numStates → ℝ) (p : Fin numAssets → ℝ)
    (h_no_arbitrage : FTAPNoArbitrage D p), ∃ q : Fin numStates → ℝ, StatePriceVector D p q

: ∀ {theta : K} (hfactor : CollateralFactor theta)
    {p : Position K} (hp : Healthy theta p) {actions : List (UserAction K)}
    (hadm : AdmissibleSequence theta p actions), (∀ q, q ∈ userTrajectory p actions → ¬ Liquidatable theta q)

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {allocation : Allocation Agent Item}
    (hEF : EnvyFree profile goods allocation), EnvyFreeUpToOneGood profile goods allocation

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {order : List Agent} {allocation : Allocation Agent Item}
    {picks : List (Agent × Item)}
    (hlog : PickLogRoundRobin profile goods order picks)
    (hmatch : PickLogMatchesAllocation allocation picks)
    (i : Agent), (picks.filterMap
        (fun p : Agent × Item => if p.1 = i then some p.2 else none)).toFinset =
      bundle goods allocation i

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {allocation : Allocation Agent Item} {i j : Agent}
    {iPicks jPicks : List Item}
    (hdom : SequentiallyDominates (profile i) iPicks jPicks)
    (hiPicks : iPicks.toFinset = bundle goods allocation i)
    (hjPicks : jPicks.toFinset = bundle goods allocation j), DoesNotEnvyUpToOneGood profile goods allocation i j

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {order : List Agent} {allocation : Allocation Agent Item}
    {picks : List (Agent × Item)}
    (hlog : PickLogRoundRobin profile goods order picks)
    (hmatch : PickLogMatchesAllocation allocation picks)
    (a : Agent), ((picks.filter fun p => p.1 = a).map Prod.snd).toFinset =
      bundle goods allocation a

: ∀ [DecidableEq Item] {jPicks : List Item}
    (hnd : jPicks.Nodup) (hnonempty : 0 < jPicks.length), jPicks.toFinset.erase (jPicks.get ⟨0, hnonempty⟩) =
      jPicks.tail.toFinset

: ∀ [DecidableEq Item]
    (v : Valuation Item K) {iPicks jPicks : List Item}
    (hdom : SequentiallyDominates v iPicks jPicks), bundleValue v jPicks.tail.toFinset ≤ bundleValue v iPicks.toFinset

[DecidableEq Item] {s : Finset Item} {l : List Item}
    (h : l.toFinset = s) (hlen : 0 < l.length) :
    l.get ⟨0, hlen⟩ ∈ s

: ∀ [DecidableEq Item]
    (v : Valuation Item K) {s t : Finset Item} {g : Item}
    (hg : g ∈ s) (hbound : bundleValue v s ≤ bundleValue v t), bundleValue v (s.erase g) ≤ bundleValue v t

: ∀ {book : Book K T} {incoming : Order K T}
    (hnot : ¬ Marketable incoming book), (incoming.side = Side.bid →
        ∀ ask, bestAsk book = some ask → incoming.price < ask)

: ∀ {book : Book K T} {incoming : Order K T}
    (hnot : ¬ Marketable incoming book), (incoming.side = Side.ask →
        ∀ bid, bestBid book = some bid → bid < incoming.price)

: ∀ {book : Book K T} {incoming : Order K T}
    (hside : incoming.side = Side.bid) {ask : K}
    (hask : bestAsk (restOrder book incoming) = some ask), bestAsk book = some ask

: ∀ {book : Book K T} {incoming : Order K T}
    (hside : incoming.side = Side.ask) {bid : K}
    (hbid : bestBid (restOrder book incoming) = some bid), bestBid book = some bid

: ∀ {book : Book K T} {incoming : Order K T}
    (hside : incoming.side = Side.bid) {bid : K}
    (hbid : bestBid (restOrder book incoming) = some bid), bid = incoming.price ∨
      ∃ oldBid, bestBid book = some oldBid ∧ bid ≤ oldBid

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {order : List Agent} {allocation : Allocation Agent Item}
    {picks : List (Agent × Item)}
    (hlog : PickLogRoundRobin profile goods order picks)
    (hmatch : PickLogMatchesAllocation allocation picks), EnvyFreeUpToOneGood profile goods allocation

: ∀ (prefW : StrictPreference Woman Man)
    {state next : ProposalState Man Woman} {activated : Man}
    {w : Woman} {rejected : Man}
    (hStep : ProposalStepRel prefW state activated next)
    (hReject : WomanRejectsManAt prefW state w rejected), WomanRejectsManAt prefW next w rejected

{Perm : Type*}
    {root : Perm} {granted boundary : Set Perm} :
    root ∈ granted ∧ root ∈ boundary → root ∈ granted ∩ boundary

: ∀ {Perm : Type*}
    {root : Perm} {granted boundary : Set Perm}, root ∈ effective ({ granted := granted, boundary := boundary } : AuthState Perm) →
      root ∈ boundary

{α : Type*} {x : α} {left right : Set α}
    (hleft : x ∉ left) (hright : x ∉ right) :
    x ∉ left ∪ right

{Perm : Type*} {root : Perm}
    {left right : Set Perm} :
    left = right → root ∈ left → root ∈ right

: ∀ {Perm : Type*} {root : Perm} {s : AuthState Perm} {ops : List (Operation Perm)}
    (hboundary : BoundaryExcludes root s)
    (hadm : AdmissibleSequence root ops), BoundaryExcludes root (postOps s ops)

: ∀ {theta : K} {p : Position K} {amount : K}
    {hamount : 0 ≤ amount} (hamount_le_collateral : amount ≤ p.collateral)
    (hguard : p.debt ≤ theta * (p.collateral - amount)), Healthy theta (applyUserAction p (withdrawAction amount hamount))

: ∀ (prefW : StrictPreference Woman Man) {w : Woman} {a b c : Man}
    (hab : WeaklyPrefers prefW w b a)
    (hbc : WeaklyPrefers prefW w c b), WeaklyPrefers prefW w c a

{Perm : Type*}
    {root : Perm} {left right : Set Perm} :
    root ∉ left → root ∉ right → root ∉ left ∪ right

{α : Type*} {x y : α} {xs : List α}
    (hmem : x ∈ xs) :
    x ∈ y :: xs
